package oepul.o6_14

# Foerderverpflichtungen der Grundmassnahme: Bestossung, Viehbesatz,
# Futtergrundlage, Pflanzenschutz, Duengung, Anwesenheit der Tiere, Meldungen.

# --- Bestossung / Mindestweidedauer ---------------------------------------

obligation_violations contains v if {
	some alm_id, _ in alm_by_id
	not alm_min_occupancy_met(alm_id)
	v := {"rule_id": "O614-GRAZE-001", "category": "obligation", "subject": alm_id, "message": sprintf("Mindestbestossungsdauer von 60 Tagen auf der Alm nicht erreicht (%d Tage).", [alm_occupied_days[alm_id]])}
}

animal_notices contains v if {
	some id, a in animal_by_id
	not meets_min_grazing(id)
	v := {"rule_id": "O614-GRAZE-001", "category": "animal_not_eligible", "subject": id, "message": sprintf("Mindestweidedauer pro Tier von 60 angerechneten Alpungstagen nicht erreicht (%d Tage); keine Praemie fuer dieses Tier.", [total_credited_days[id]])}
}

animal_notices contains v if {
	some id, a in animal_by_id
	not species_eligible(a)
	v := {"rule_id": "O614-ANIMAL-001", "category": "animal_not_eligible", "subject": id, "message": "Tierart ist keine teilnahmefaehige RGVE."}
}

animal_notices contains v if {
	some id, a in animal_by_id
	count([s | some s in stays(a); valid_stay(s)]) > 0
	not driven_up_in_time(a)
	v := {"rule_id": "O614-APPL-010", "category": "animal_not_eligible", "subject": id, "message": "Tier nicht bis spaetestens 15. Juli aufgetrieben; keine Anerkennung fuer die Auszahlung."}
}

# Tiere muessen sich grundsaetzlich Tag und Nacht auf der Alm befinden.
animal_notices contains v if {
	some id, a in animal_by_id
	not presence_compliant(a)
	v := {"rule_id": "O614-GRAZE-008", "category": "animal_not_eligible", "subject": id, "message": "Anwesenheit auf der Alm (Tag und Nacht, max. halber Tag im Almstall) nicht erfuellt; keine Praemie."}
}

reporting_violations contains v if {
	some id, a in animal_by_id
	not presence_compliant(a)
	is_false(a, "non_compliance_reported")
	v := {"rule_id": "O614-GRAZE-008", "category": "reporting", "subject": id, "message": "Nichteinhaltung der Anwesenheit ist der AMA zu melden (bei Rindern online ueber eAMA)."}
}

obligation_violations contains v if {
	some id, a in animal_by_id
	is_false(a, "home_stable_only_for_milking")
	some s in stays(a)
	alm_by_id[s.alm_id].adjacent_to_home_farm == true
	v := {"rule_id": "O614-GRAZE-009", "category": "obligation", "subject": id, "message": "Bei an das Heimgut angrenzenden Almen duerfen die Tiere im Heimstall nur fuer die Dauer des Melkvorganges verbleiben."}
}

# --- Maximaler Viehbesatz ----------------------------------------------------

obligation_violations contains v if {
	some alm_id, _ in alm_by_id
	overstocked(alm_id)
	v := {"rule_id": "O614-STOCK-001", "category": "obligation", "subject": alm_id, "message": sprintf("Ueberbesatz: %.2f RGVE/ha > zulaessig %.2f RGVE/ha.", [alm_stocking_density[alm_id], alm_max_stocking_limit[alm_id]])}
}

# --- Natuerliche Futtergrundlage --------------------------------------------

feeding(alm) := object.get(alm, "feeding", {})

obligation_violations contains v if {
	some alm in alms
	is_true(feeding(alm), "basic_fodder_supplementation")
	v := {"rule_id": "O614-FEED-001", "category": "obligation", "subject": alm.alm_id, "message": "Zufuetterung mit Grundfutter ist nicht erlaubt (nur Ausgleichsfuetterung)."}
}

obligation_violations contains v if {
	some alm in alms
	is_true(feeding(alm), "alm_foreign_green_fodder_fed")
	v := {"rule_id": "O614-FEED-003", "category": "obligation", "subject": alm.alm_id, "message": "Verfuetterung von almfremdem Gruenfutter ist verboten."}
}

obligation_violations contains v if {
	some alm in alms
	is_true(feeding(alm), "silage_fed")
	not silage_feeding_allowed(alm)
	v := {"rule_id": "O614-FEED-003", "category": "obligation", "subject": alm.alm_id, "message": "Verfuetterung von Silage ist verboten (ab 2025 nur almeigene Silage)."}
}

silage_feeding_allowed(alm) if {
	year >= 2025
	is_true(feeding(alm), "silage_alm_own")
	not heuwirtschaft_own_alm(alm)
}

obligation_violations contains v if {
	some alm in alms
	is_true(feeding(alm), "alm_silage_moved_to_home_farm")
	v := {"rule_id": "O614-FEED-004", "category": "obligation", "subject": alm.alm_id, "message": "Auf der Almweideflaeche produzierte Silage muss gaenzlich auf der jeweiligen Alm verfuettert werden."}
}

heuwirtschaft_own_alm(alm) if {
	participates_in("heuwirtschaft")
	is_true(alm, "is_own_alm")
}

obligation_violations contains v if {
	some alm in alms
	heuwirtschaft_own_alm(alm)
	silage_activity(feeding(alm))
	v := {"rule_id": "O614-FEED-006", "category": "obligation", "subject": alm.alm_id, "message": "Eigenalm bei Teilnahme an Heuwirtschaft: keine Silage erzeugen, fuettern oder lagern (auch nicht auf der Alm)."}
}

silage_activity(f) if is_true(f, "silage_fed")

silage_activity(f) if is_true(f, "silage_produced")

silage_activity(f) if is_true(f, "silage_stored")

# --- Pflanzenschutz ----------------------------------------------------------

plant_protection(alm) := object.get(alm, "plant_protection", {})

obligation_violations contains v if {
	some alm in alms
	is_true(plant_protection(alm), "non_organic_psm_used")
	v := {"rule_id": "O614-PSM-001", "category": "obligation", "subject": alm.alm_id, "message": "Einsatz von Pflanzenschutzmitteln, die nicht gemaess VO (EU) 2018/848 zulaessig sind."}
}

psm_coding_required(y) if {
	some c in proc.psm_codes
	y <= c.required_until_year
}

required_psm_code(types) := "PSMCS" if "chemical_synthetic" in types

required_psm_code(types) := "PSMBIO" if {
	"organic" in types
	not "chemical_synthetic" in types
}

reporting_violations contains v if {
	psm_coding_required(year)
	some alm in alms
	some plot in object.get(alm, "plots", [])
	types := object.get(plot, "area_wide_psm_types", [])
	count(types) > 0
	code := required_psm_code(types)
	not psm_code_present(plot, code)
	v := {"rule_id": "O614-PSM-002", "category": "reporting", "subject": plot.plot_id, "message": sprintf("Flaechiger PSM-Einsatz bis Antragsjahr 2025 mit Code %s zu erfassen.", [code])}
}

psm_code_present(plot, code) if code in object.get(plot, "codes", [])

# --- Duengung ------------------------------------------------------------------

fertilisation(alm) := object.get(alm, "fertilisation", {})

fertiliser_breaches := {
	"non_organic_fertiliser_used": ["O614-FERT-001", "Ausbringung von Duengemitteln, die nicht gemaess VO (EU) 2018/848 zugelassen sind."],
	"alm_foreign_slurry_applied": ["O614-FERT-002", "Ausbringung almfremder Guelle oder Jauche."],
	"sewage_sludge_applied": ["O614-FERT-003", "Ausbringung von Klaerschlamm oder kompostiertem Klaerschlamm."],
	"home_farm_separated_slurry_solids_applied": ["O614-FERT-004", "Separierter Guelleanteil in fester Form vom Heimbetrieb ist nicht zulaessig."],
}

obligation_violations contains v if {
	some alm in alms
	some key, spec in fertiliser_breaches
	is_true(fertilisation(alm), key)
	v := {"rule_id": spec[0], "category": "obligation", "subject": alm.alm_id, "message": spec[1]}
}

# --- Meldefristen Auf- und Abtrieb ------------------------------------------

reporting_violations contains v if {
	some id, a in animal_by_id
	w := reporting_window(a.species)
	some s in stays(a)
	valid_stay(s)
	s.drive_up_report_date
	days_between(s.drive_up_date, s.drive_up_report_date) > w.drive_up_report_days
	v := {"rule_id": "O614-GRAZE-006", "category": "reporting", "subject": id, "message": sprintf("Auftrieb nicht binnen %d Tagen gemeldet; Anrechnung erst %d Tage vor dem Meldedatum.", [w.drive_up_report_days, w.max_credit_days_before_report])}
}

reporting_violations contains v if {
	some id, a in animal_by_id
	w := reporting_window(a.species)
	some s in stays(a)
	valid_stay(s)
	down_report_late(a, s, w)
	v := {"rule_id": "O614-GRAZE-007", "category": "reporting", "subject": id, "message": sprintf("Abtrieb/Abgang nicht binnen %d Tagen ab dem tatsaechlichen Abtrieb gemeldet.", [w.drive_down_report_days])}
}

# Equiden und Neuweltkamele: stimmt das beim Auftrieb angegebene
# voraussichtliche Abtriebsdatum, ist keine Nachmeldung erforderlich.
down_report_late(a, s, w) if {
	not planned_date_matches(a, s)
	s.drive_down_report_date
	days_between(s.drive_down_date, s.drive_down_report_date) > w.drive_down_report_days
}

down_report_late(a, s, _) if {
	not planned_date_matches(a, s)
	not s.drive_down_report_date
}

planned_date_matches(a, s) if {
	a.species in {"equine", "new_world_camelid"}
	s.planned_drive_down_date == s.drive_down_date
}

reporting_violations contains v if {
	some id, a in animal_by_id
	a.species in {"sheep", "goat"}
	not a.ear_tag
	v := {"rule_id": "O614-APPL-012", "category": "reporting", "subject": id, "message": "Schafe und Ziegen sind einzeltierbezogen mit Ohrmarke zu beantragen."}
}

reporting_violations contains v if {
	some id, a in animal_by_id
	a.species in {"sheep", "goat"}
	is_true(a, "sold_without_drive_down")
	is_true(a, "in_tierwohl_weide_or_rare_breeds")
	is_false(a, "new_drive_up_report_with_new_home_farm")
	v := {"rule_id": "O614-APPL-013", "category": "reporting", "subject": id, "message": "Verkauf ohne Abtrieb: erneute Auftriebsmeldung mit der neuen Heimbetriebsnummer erforderlich."}
}

violations := ((((access_violations | deadline_violations) | obligation_violations) | reporting_violations) | nata_violations) | awp_violations

default obligations_met := false

obligations_met if count(obligation_violations | nata_violations) == 0

package oepul.o6_14

# Teilnahmevoraussetzungen, Vertragszeitraum, Antrags- und Einstiegsfristen.

commitment_start_year := object.get(measure_input, "commitment_start_year", null)

contract_period := p if {
	some p in proc.contract_periods
	p.start_year == commitment_start_year
}

contract_end_date := contract_period.end_date

contract_duration_years := contract_period.duration_years

first_commitment_year if year == commitment_start_year

# Massnahmenantrag vor Vertragsbeginn bis 31.12. des Vorjahres.
application_deadline_for(start_year) := deadline_date("measure_application", start_year - 1)

measure_application_timely if {
	is_true(measure_input, "applied")
	on_or_before(measure_input.application_date, application_deadline_for(commitment_start_year))
}

# Letzter Einstieg: Foerderjahr 2025 (Beantragung bis 31.12.2024).
measure_entry_year_allowed if {
	commitment_start_year >= 2023
	commitment_start_year <= last_entry("measure").last_commitment_year
}

takeover := object.get(af, "takeover", {})

takeover_valid if {
	is_true(takeover, "is_takeover")
	on_or_before(takeover.submission_date, deadline_date("measure_takeover", year))
	is_false(takeover, "previously_participating")
	object.get(takeover, "expansion_share", 0) <= 0.5
	is_true(takeover, "approved_by_ama")
}

valid_contract if {
	measure_application_timely
	measure_entry_year_allowed
}

valid_contract if takeover_valid

# --- Foerderwerbende Person ---------------------------------------------------

applicant := object.get(input.farm, "applicant", {})

applicant_type_eligible if {
	some row in proc.eligible_applicant_types
	row.legal_form == applicant.legal_form
	row.public_body_share_limit_pct == null
}

applicant_type_eligible if {
	some row in proc.eligible_applicant_types
	row.legal_form == applicant.legal_form
	row.public_body_share_limit_pct != null
	object.get(applicant, "public_body_share_pct", 0) <= row.public_body_share_limit_pct
}

# --- Mindestteilnahme im ersten Teilnahmejahr --------------------------------

total_alm_area_ha := sum([alm.alm_pasture_area_ha | some alm in alms])

total_participating_rgve := sum([animal_rgve(a) |
	some id, a in animal_by_id
	animal_premium_eligible(id)
])

minimum_participation_met if {
	total_alm_area_ha >= proc.minimum_participation_first_year.alm_pasture_area_ha
	total_participating_rgve >= proc.minimum_participation_first_year.rgve
}

# Betriebsmindestgroesse im ersten OePUL-Teilnahmejahr.
first_oepul_year if year == object.get(object.get(input.farm, "oepul", {}), "first_oepul_year", null)

farm_min_size_met if object.get(object.get(input, "land", {}), "protected_cultivation_area_ha", 0) >= proc.minimum_farm_size_first_oepul_year.protected_cultivation_ha

farm_min_size_met if object.get(object.get(input, "land", {}), "total_area_ha", 0) >= proc.minimum_farm_size_first_oepul_year.agricultural_area_ha

access_violations contains v if {
	not is_true(af, "is_alm_manager")
	v := {"rule_id": "O614-SCOPE-002", "category": "access", "subject": "farm", "message": "Die Massnahme ist von der almbewirtschaftenden Person zu beantragen."}
}

access_violations contains v if {
	not valid_contract
	v := {"rule_id": "O614-APPL-001", "category": "access", "subject": "farm", "message": "Kein gueltiger Vertrag: Massnahmenantrag nicht bis 31.12. vor Vertragsbeginn, Einstiegsjahr nach 2025 oder keine gueltige Massnahmenuebernahme."}
}

access_violations contains v if {
	not applicant_type_eligible
	v := {"rule_id": "O614-ACCESS-005", "category": "access", "subject": "farm", "message": "Rechtsform nicht foerderfaehig oder Beteiligung von Gebietskoerperschaften ueber 25 %."}
}

access_violations contains v if {
	is_false(applicant, "is_active_farmer")
	v := {"rule_id": "O614-ACCESS-006", "category": "access", "subject": "farm", "message": "Aktiver Landwirt / landwirtschaftliche Taetigkeit nicht erfuellt."}
}

access_violations contains v if {
	first_commitment_year
	not minimum_participation_met
	v := {"rule_id": "O614-ACCESS-001", "category": "access", "subject": "farm", "message": sprintf("Mindestteilnahme im ersten Teilnahmejahr nicht erfuellt (%.2f ha, %.2f RGVE; erforderlich je 3,00).", [total_alm_area_ha, total_participating_rgve])}
}

access_violations contains v if {
	first_oepul_year
	not farm_min_size_met
	v := {"rule_id": "O614-ACCESS-007", "category": "access", "subject": "farm", "message": "Betriebsmindestgroesse im ersten OePUL-Teilnahmejahr nicht erreicht."}
}

default access_conditions_met := false

access_conditions_met if count(access_violations) == 0

# Rechtsfolge: im 1. Jahr kein Vertrag, ab dem 2. Verpflichtungsjahr keine
# Praemie im betroffenen Jahr.
access_consequence := "no_contract" if {
	not access_conditions_met
	first_commitment_year
}

access_consequence := "no_premium_this_year" if {
	not access_conditions_met
	not first_commitment_year
}

access_consequence := "none" if access_conditions_met

# --- Zuschlaege: Einstieg ---------------------------------------------------

deadline_violations contains v if {
	nata_applied
	nata_start := object.get(nata_input, "commitment_start_year", commitment_start_year)
	nata_start > last_entry("nature_conservation_supplement").last_commitment_year
	v := {"rule_id": "O614-APPL-002", "category": "deadline", "subject": "nature_conservation_supplement", "message": "Letzter Einstieg in den Zuschlag Naturschutz auf der Alm ist das Foerderjahr 2025."}
}

deadline_violations contains v if {
	nata_applied
	nata_start := object.get(nata_input, "commitment_start_year", commitment_start_year)
	not on_or_before(nata_input.application_date, application_deadline_for(nata_start))
	v := {"rule_id": "O614-APPL-001", "category": "deadline", "subject": "nature_conservation_supplement", "message": "Zuschlag Naturschutz auf der Alm nicht bis 31.12. vor Vertragsbeginn beantragt."}
}

deadline_violations contains v if {
	awp_applied
	first := object.get(awp_input, "first_application_year", year)
	not awp_entry_year_allowed(first)
	v := {"rule_id": "O614-APPL-003", "category": "deadline", "subject": "grazing_plan_supplement", "message": "Zuschlag Almweideplan nur fuer Foerderjahre 2025 bis 2028 beantragbar."}
}

deadline_violations contains v if {
	awp_applied
	first := object.get(awp_input, "first_application_year", year)
	not on_or_before(awp_input.application_date, application_deadline_for(first))
	v := {"rule_id": "O614-APPL-001", "category": "deadline", "subject": "grazing_plan_supplement", "message": "Zuschlag Almweideplan nicht bis 31.12. vor dem Foerderjahr im Massnahmenantrag beantragt."}
}

awp_entry_year_allowed(y) if {
	y >= last_entry("grazing_plan_supplement").first_commitment_year
	y <= last_entry("grazing_plan_supplement").last_commitment_year
}

# Feldstuecksliste bis 15.04. (2023/2028: 17.04.).
deadline_violations contains v if {
	some alm in alms
	alm.field_list_submission_date
	after(alm.field_list_submission_date, deadline_date("field_list_area_application", year))
	v := {"rule_id": "O614-APPL-004", "category": "deadline", "subject": alm.alm_id, "message": "Almweideflaechen nicht fristgerecht in der Feldstuecksliste beantragt."}
}

# Alm/Gemeinschaftsweide-Auftriebsliste (Zahlungsantrag) bis 15.07.
drive_up_list_required(alm) if not cattle_only_alm(alm.alm_id)

drive_up_list_required(alm) if alm_access_level[alm.alm_id] != 1

drive_up_list_required(_) if participates_in("tierwohl_behirtung")

drive_up_list_required(alm) if awp_increased_intensity(alm)

deadline_violations contains v if {
	some alm in alms
	drive_up_list_required(alm)
	not alm.drive_up_list_submission_date
	v := {"rule_id": "O614-APPL-005", "category": "deadline", "subject": alm.alm_id, "message": "Alm/Gemeinschaftsweide-Auftriebsliste (Zahlungsantrag) fehlt."}
}

deadline_violations contains v if {
	some alm in alms
	drive_up_list_required(alm)
	alm.drive_up_list_submission_date
	after(alm.drive_up_list_submission_date, deadline_date("drive_up_list", year))
	v := {"rule_id": "O614-APPL-005", "category": "deadline", "subject": alm.alm_id, "message": "Alm/Gemeinschaftsweide-Auftriebsliste nach dem 15.07. (2023/2028: 17.07.) eingereicht."}
}

# NATA-Codierung aller Schlaege bis 15.04. (2023/2028: 17.04.).
deadline_violations contains v if {
	some alm in alms
	nata_alm(alm)
	some plot in object.get(alm, "plots", [])
	not "NATA" in object.get(plot, "codes", [])
	v := {"rule_id": "O614-APPL-015", "category": "deadline", "subject": plot.plot_id, "message": "Schlag der Naturschutz-Alm nicht mit Code NATA gekennzeichnet."}
}

deadline_violations contains v if {
	some alm in alms
	nata_alm(alm)
	alm.nata_coding_date
	after(alm.nata_coding_date, deadline_date("nata_coding", year))
	v := {"rule_id": "O614-APPL-015", "category": "deadline", "subject": alm.alm_id, "message": "NATA-Codierung nach dem 15.04. (2023/2028: 17.04.)."}
}

deadline_violations contains v if {
	some alm in alms
	awp_increased_intensity(alm)
	drive_up_list_required(alm)
	is_false(object.get(alm, "grazing_plan", {}), "increased_intensity_declared_in_drive_up_list")
	v := {"rule_id": "O614-APPL-007", "category": "deadline", "subject": alm.alm_id, "message": "Almweideplan mit Auftrieb bis 2,40 RGVE/ha ist in der Auftriebsliste zu beantragen."}
}

package oepul.o6_14

# Maximaler Viehbesatz je Alm (2,00 / 1,50 NATA / 2,40 Almweideplan) und
# Mindestbestossungsdauer je Alm.

alm_stocking_rgve[alm_id] := x if {
	some alm_id, _ in alm_by_id
	x := sum([stocking_rgve_share(id, alm_id) |
		some id, _ in animal_by_id
		counts_for_stocking(id)
	])
}

# Auslaendische angrenzende Almflaechen entlasten den Viehbesatz nur bei
# jaehrlicher gesonderter Meldung mit Nachweis.
foreign_relief_ha(alm) := object.get(alm, "foreign_adjacent_area_ha", 0) if is_true(alm, "foreign_area_report_submitted")

foreign_relief_ha(alm) := 0 if not is_true(alm, "foreign_area_report_submitted")

stocking_area_ha(alm) := alm.alm_pasture_area_ha + foreign_relief_ha(alm)

alm_stocking_density[alm_id] := alm_stocking_rgve[alm_id] / stocking_area_ha(alm) if {
	some alm_id, alm in alm_by_id
	stocking_area_ha(alm) > 0
}

awp_increased_intensity(alm) if {
	awp_applied
	year >= 2025
	gp := object.get(alm, "grazing_plan", {})
	is_true(gp, "increased_intensity_applied")
	is_true(gp, "increased_intensity_justified_in_plan")
}

nata_alm(alm) if {
	nata_applied
	is_true(object.get(alm, "nature_conservation", {}), "participates")
}

max_stocking_limit(alm) := 1.5 if nata_alm(alm)

max_stocking_limit(alm) := 2.4 if {
	not nata_alm(alm)
	awp_increased_intensity(alm)
}

max_stocking_limit(alm) := 2.0 if {
	not nata_alm(alm)
	not awp_increased_intensity(alm)
}

alm_max_stocking_limit[alm_id] := max_stocking_limit(alm) if some alm_id, alm in alm_by_id

overstocked(alm_id) if alm_stocking_density[alm_id] > alm_max_stocking_limit[alm_id]

alm_min_occupancy_met(alm_id) if alm_occupied_days[alm_id] >= min_grazing_days

package oepul.o6_14

# Optionale Zuschlaege "Naturschutz auf der Alm" (NATA) und "Almweideplan".

# --- Naturschutz auf der Alm -----------------------------------------------------

project_confirmation_all_plots(alm) if {
	plots := object.get(alm, "plots", [])
	count(plots) > 0
	every plot in plots {
		is_true(plot, "project_confirmation")
	}
}

nature(alm) := object.get(alm, "nature_conservation", {})

nata_forbidden_fertilised_habitats := {"moor", "wetland", "calcareous_grassland", "siliceous_grassland"}

nata_violations contains v if {
	some alm in alms
	nata_alm(alm)
	not project_confirmation_all_plots(alm)
	v := {"rule_id": "O614-ACCESS-004", "category": "access", "subject": alm.alm_id, "message": "Zuschlag Naturschutz auf der Alm erfordert eine Projektbestaetigung fuer alle Feldstuecke der Alm."}
}

nata_violations contains v if {
	some alm in alms
	nata_alm(alm)
	is_false(nature(alm), "project_requirements_met")
	v := {"rule_id": "O614-NATA-001", "category": "obligation", "subject": alm.alm_id, "message": "Bewirtschaftungsauflagen gemaess Projektbestaetigung nicht auf allen Feldstuecken eingehalten."}
}

nata_violations contains v if {
	some alm in alms
	nata_alm(alm)
	some h in object.get(nature(alm), "fertilised_habitats", [])
	h in nata_forbidden_fertilised_habitats
	v := {"rule_id": "O614-NATA-003", "category": "obligation", "subject": alm.alm_id, "message": sprintf("Duengung in %s verboten (Ausnahme nur Borstgrasrasen).", [h])}
}

nata_violations contains v if {
	some alm in alms
	nata_alm(alm)
	some key in ["terrain_correction", "new_drainage"]
	is_true(nature(alm), key)
	v := {"rule_id": "O614-NATA-004", "category": "obligation", "subject": alm.alm_id, "message": sprintf("Unzulaessige Massnahme: %s.", [key])}
}

nata_violations contains v if {
	some alm in alms
	nata_alm(alm)
	is_true(nature(alm), "drainage_upgraded")
	not is_true(nature(alm), "drainage_upgrade_consent")
	v := {"rule_id": "O614-NATA-004", "category": "obligation", "subject": alm.alm_id, "message": "Bestehende Drainagen nur im Einvernehmen mit der Naturschutzstelle des Landes ertuechtigen."}
}

nata_violations contains v if {
	some alm in alms
	nata_alm(alm)
	is_true(nature(alm), "watering_point_in_wetland_or_spring")
	v := {"rule_id": "O614-NATA-005", "category": "obligation", "subject": alm.alm_id, "message": "Traenkestellen duerfen nicht in Feuchtflaechen oder Quellfluren errichtet werden."}
}

nata_violations contains v if {
	some alm in alms
	nata_alm(alm)
	some m in nata_measures(alm)
	not valid_nata_code(m.code)
	v := {"rule_id": "O614-NATA-011", "category": "obligation", "subject": alm.alm_id, "message": sprintf("Unbekannter Auflagencode %s gemaess Anhang E.", [m.code])}
}

valid_nata_code(code) if {
	some r in rates.nature_conservation_measure_codes
	r.code == code
}

nata_course := object.get(nata_input, "course", {})

nata_course_valid if {
	is_true(nata_course, "completed")
	nata_course.hours >= proc.nature_conservation_course.min_hours
	on_or_before(nata_course.completion_date, proc.nature_conservation_course.deadline)
	on_or_before(proc.nature_conservation_course.creditable_from, nata_course.completion_date)
	is_true(nata_course, "provider_recognized")
	is_true(nata_course, "content_nature_conservation_related")
	nata_course.attendee_role in {"alm_manager", "herder", "significantly_involved_person"}
	not is_true(nata_course, "credited_to_other_farm")
	not is_true(nata_course, "double_counted")
	not trained_person_left_without_replacement
}

trained_person_left_without_replacement if {
	is_true(nata_course, "trained_person_left_date_known")
	on_or_before(nata_course.trained_person_left_date, proc.nature_conservation_course.deadline)
	not is_true(nata_course, "replacement_course_completed")
}

# Kurspflicht besteht ab dem Jahr, in dem die Frist 31.12.2025 abgelaufen ist
# bzw. der Kurs bereits absolviert sein muss.
nata_violations contains v if {
	nata_applied
	year >= 2025
	not nata_course_valid
	v := {"rule_id": "O614-NATA-006", "category": "obligation", "subject": "nature_conservation_supplement", "message": "Fachspezifischer Kurs (mind. 4 Stunden, anerkannter Bildungsanbieter, ab 01.01.2022, bis 31.12.2025) nicht nachgewiesen."}
}

nata_violations contains v if {
	nata_applied
	awp_applied
	not supplements_combinable("grazing_plan", "nature_conservation")
	v := {"rule_id": "O614-AWP-008", "category": "combination", "subject": "farm", "message": "Zuschlag Almweideplan ist nicht mit dem Zuschlag Naturschutz auf der Alm kombinierbar."}
}

# --- Almweideplan -----------------------------------------------------------

awp_course := object.get(awp_input, "course", {})

awp_plan := object.get(awp_input, "plan", {})

awp_first_year := object.get(awp_input, "first_application_year", year)

awp_course_valid if {
	is_true(awp_course, "completed")
	awp_course.hours >= proc.grazing_plan_course.min_hours
	on_or_before(proc.grazing_plan_course.creditable_from, awp_course.completion_date)
	on_or_before(awp_course.completion_date, deadline_date("grazing_plan_course", awp_first_year))
	is_true(awp_course, "provider_recognized")
	is_true(awp_course, "covers_required_topics")
	awp_course.attendee_role in {"farm_manager", "alm_manager", "significantly_involved_person"}
	not is_true(awp_course, "credited_to_other_farm")
	not is_true(awp_course, "double_counted")
}

awp_plan_contents := [
	"covers_all_alms",
	"assessment_site_yield",
	"assessment_ecological_value",
	"development_goals_and_management_needs",
	"grazing_and_steering_measures_per_plot",
	"created_with_or_communicated_to_involved_persons",
]

awp_obligation_violations contains v if {
	awp_applied
	not awp_course_valid
	v := {"rule_id": "O614-AWP-002", "category": "obligation", "subject": "grazing_plan_supplement", "message": "Bildungsveranstaltung Almweideplan (mind. 4 Stunden, ab 01.10.2024, bis 15.07. des ersten Jahres) nicht nachgewiesen."}
}

awp_obligation_violations contains v if {
	awp_applied
	not awp_plan.created_date
	v := {"rule_id": "O614-AWP-003", "category": "obligation", "subject": "grazing_plan_supplement", "message": "Almweideplan nicht erstellt."}
}

awp_obligation_violations contains v if {
	awp_applied
	awp_plan.created_date
	after(awp_plan.created_date, deadline_date("grazing_plan_creation", year))
	v := {"rule_id": "O614-AWP-003", "category": "obligation", "subject": "grazing_plan_supplement", "message": "Almweideplan nicht bis 15.07. des Teilnahmejahres erstellt."}
}

awp_obligation_violations contains v if {
	awp_applied
	some key in awp_plan_contents
	not is_true(awp_plan, key)
	v := {"rule_id": "O614-AWP-004", "category": "obligation", "subject": "grazing_plan_supplement", "message": sprintf("Almweideplan unvollstaendig: %s.", [key])}
}

awp_obligation_violations contains v if {
	awp_applied
	year > awp_first_year
	not is_true(awp_plan, "annual_review_documented")
	v := {"rule_id": "O614-AWP-005", "category": "obligation", "subject": "grazing_plan_supplement", "message": "Ab dem zweiten Teilnahmejahr jaehrliche dokumentierte Ueberpruefung des Almweideplans erforderlich."}
}

awp_obligation_violations contains v if {
	awp_applied
	some alm in alms
	gp := object.get(alm, "grazing_plan", {})
	is_true(gp, "increased_intensity_applied")
	not is_true(gp, "increased_intensity_justified_in_plan")
	v := {"rule_id": "O614-AWP-006", "category": "obligation", "subject": alm.alm_id, "message": "Verstaerkte Weideintensitaet (bis 2,40 RGVE/ha) erfordert eine Begruendung im Almweideplan."}
}

awp_violations := awp_obligation_violations

# Almweideplan: einjaehriger Vertragszeitraum, automatische Verlaengerung.
awp_active_next_year if {
	awp_applied
	not is_true(awp_input, "deregistered")
	year + 1 <= last_entry("grazing_plan_supplement").last_commitment_year
}

awp_takeover_allowed(context) if {
	some row in combos.takeover_only_in_individual_cases
	row.item == "grazing_plan_supplement"
	context in row.allowed_contexts
}

